434	func TestRegistryHealthPreservedAcrossRegistration(t *testing.T) {
435		r := NewRegistry()
436		registerService(t, r, "svc", 0, []Instance{{ID: "a", Address: "h:1"}, {ID: "b", Address: "h:2"}})
437	
438		// Observe both instances.
439		upd, _ := r.ValidateHealth("svc", "a", 1, 1, true, "")
440		r.ApplyHealth(upd)
441		upd, _ = r.ValidateHealth("svc", "b", 1, 2, false, "down")
442		r.ApplyHealth(upd)
443	
444		// Re-register with identical content: health and revision preserved.
445		reg, _ := r.ValidateRegistration("svc", 1, []Instance{{ID: "b", Address: "h:2"}, {ID: "a", Address: "h:1"}})
446		out := r.Apply(reg)
447		if !out.OK || out.Changed || out.Revision != 1 {
448			t.Fatalf("identical re-registration: %+v", out)
449		}
450		if inst := instanceHealth(t, r, "svc", "a"); inst.Health != HealthHealthy || inst.Sequence != 1 {
451			t.Fatalf("a health not preserved: %+v", inst)
452		}
453		if inst := instanceHealth(t, r, "svc", "b"); inst.Health != HealthUnhealthy || inst.Sequence != 2 || inst.Reason != "down" {
454			t.Fatalf("b health not preserved: %+v", inst)
455		}
456	
457		// Address change resets to unknown/0.
458		reg, _ = r.ValidateRegistration("svc", 1, []Instance{{ID: "a", Address: "h:9"}, {ID: "b", Address: "h:2"}})
459		out = r.Apply(reg)
460		if !out.OK || !out.Changed || out.Revision != 2 {
461			t.Fatalf("address change: %+v", out)
462		}
463		if inst := instanceHealth(t, r, "svc", "a"); inst.Health != HealthUnknown || inst.Sequence != 0 {
464			t.Fatalf("a should reset after address change: %+v", inst)
465		}
466		// b kept its address, so its observation survives.
467		if inst := instanceHealth(t, r, "svc", "b"); inst.Health != HealthUnhealthy || inst.Sequence != 2 {
468			t.Fatalf("b should keep health: %+v", inst)
469		}
470	
471		// A health result collected under the old revision is rejected even though
472		// the instance and its new address exist.
473		upd, _ = r.ValidateHealth("svc", "a", 1, 3, true, "")
474		hout := r.ApplyHealth(upd)
475		if hout.OK || hout.Kind != OutcomeConflict || hout.Actual != 2 {
476			t.Fatalf("old revision result: %+v", hout)
477		}
478	
479		// New revision accepts the observation on the reset instance.
480		upd, _ = r.ValidateHealth("svc", "a", 2, 3, true, "")
481		hout = r.ApplyHealth(upd)
482		if !hout.OK || !hout.Changed || hout.Sequence != 3 {
483			t.Fatalf("new revision result: %+v", hout)
484		}
485	}
