153	// TestSnapshotCallerMutationCannotChangeRegistry fixes the display-side
154	// convention: a caller may freely overwrite the service name, revision,
155	// instance identity, address, health, sequence, reason and list membership of
156	// a returned snapshot. None of that reaches the registry — a fresh snapshot
157	// still shows the accepted truth and target selection still returns the real
158	// healthy instance's address and sequence.
159	func TestSnapshotCallerMutationCannotChangeRegistry(t *testing.T) {
160		r := NewRegistry()
161		registerService(t, r, "svc", 0, []Instance{
162			{ID: "a", Address: "h:1"},
163			{ID: "b", Address: "h:2"},
164		})
165		markHealth(t, r, "svc", "a", 1, 7, true, "")
166		markHealth(t, r, "svc", "b", 1, 8, false, "down")
167	
168		saved := r.Snapshot()
169		view := &saved[0]
170		view.Service = "tampered" // service information
171		view.Revision = 999
172		view.Instances[0].ID = "z"
173		view.Instances[0].Address = "x:9" // instance address
174		view.Instances[0].Health = HealthUnhealthy
175		view.Instances[0].Sequence = 123 // health state and sequence
176		view.Instances[0].Reason = "fake"
