186			t.Fatalf("accepted service state changed after mutating a snapshot: %+v", fresh)
187		}
188		want := map[string]InstanceView{
189			"a": {ID: "a", Address: "h:1", Health: HealthHealthy, Sequence: 7, Reason: ""},
190			"b": {ID: "b", Address: "h:2", Health: HealthUnhealthy, Sequence: 8, Reason: "down"},
