208	// TestConsecutiveSnapshotsAreIndependent fixes that two reads back to back own
209	// separate storage: adjusting fields or list membership of one snapshot must
210	// neither contaminate the other nor leak back into the first once the second
211	// is adjusted as well.
212	func TestConsecutiveSnapshotsAreIndependent(t *testing.T) {
213		r := NewRegistry()
214		registerService(t, r, "svc", 0, []Instance{
215			{ID: "a", Address: "h:1"},
216			{ID: "b", Address: "h:2"},
217		})
218		markHealth(t, r, "svc", "a", 1, 1, true, "")
219		markHealth(t, r, "svc", "b", 1, 2, false, "down")
220	
221		first := r.Snapshot()
222		second := r.Snapshot()
223	
224		// Adjust the first snapshot in every shape a display caller might.
225		first[0].Service = "renamed"
226		first[0].Revision = 42
227		first[0].Instances[0].Address = "changed:1"
228		first[0].Instances[0].Health = HealthUnhealthy
229		first[0].Instances[0].Sequence = 99
230		first[0].Instances[0].Reason = "made up"
231		first[0].Instances = append(first[0].Instances, InstanceView{ID: "ghost"})
232		first[0].Instances[1] = InstanceView{}
233	
234		// The second snapshot keeps its own read-time values.
235		if len(second) != 1 || second[0].Service != "svc" || second[0].Revision != 1 || len(second[0].Instances) != 2 {
236			t.Fatalf("second snapshot contaminated by adjusting the first: %+v", second)
237		}
238		wantSecond := map[string]InstanceView{
239			"a": {ID: "a", Address: "h:1", Health: HealthHealthy, Sequence: 1, Reason: ""},
240			"b": {ID: "b", Address: "h:2", Health: HealthUnhealthy, Sequence: 2, Reason: "down"},
241		}
