248		// Adjusting the second snapshot must not reach back into the first.
249		second[0].Instances[0].Sequence = 77
250		if got := first[0].Instances[0]; got.Sequence != 99 || got.Health != HealthUnhealthy || got.Reason != "made up" {
251			t.Fatalf("the two snapshots share storage; adjusting the second reached the first: %+v", got)
252		}
253	}
