255	// TestSnapshotReadsDoNotAdvanceRevisionHealthOrCursor fixes that reading and
256	// adjusting snapshots is observation-only: it must not consume a registration
257	// revision, alter accepted health records or move the per-service selection
258	// cursor.
259	func TestSnapshotReadsDoNotAdvanceRevisionHealthOrCursor(t *testing.T) {
260		r := NewRegistry()
261		registerService(t, r, "svc", 0, []Instance{
262			{ID: "a", Address: "h:1"},
263			{ID: "b", Address: "h:2"},
264		})
