293			t.Fatalf("snapshot reads moved the selection cursor: %+v", out)
294		}
295	}
296	
297	// TestSnapshotEmptyRegistryReturnsEmptyList fixes the empty-registry
298	// boundary: a read returns an empty list, repeatedly.
299	func TestSnapshotEmptyRegistryReturnsEmptyList(t *testing.T) {
300		r := NewRegistry()
