317			t.Fatalf("empty-instance service should appear at revision 1: %+v", views)
318		}
319	
320		// Populate, then replace with an empty list: the service stays in the
321		// result and carries the post-replacement revision.
322		registerService(t, r, "svc", 1, []Instance{{ID: "a", Address: "h:1"}})
323		registerService(t, r, "svc", 2, nil)
324		views := r.Snapshot()
325		if len(views) != 1 || views[0].Service != "svc" || views[0].Revision != 3 {
326			t.Fatalf("emptied service should appear at the new revision 3: %+v", views)
327		}
328		if len(views[0].Instances) != 0 {
329			t.Fatalf("emptied service should carry no instances: %+v", views[0].Instances)
330		}
