1190		if r := got.Results[9]; r.OK || r.Error != "no_healthy" || r.Reason == "" ||
1191			r.Revision != 3 || r.InstanceID != "" || r.Address != "" {
1192			t.Fatalf("result 9 no_healthy after re-register: %+v", r)
1193		}
1194		// 10-12: observations under the pre-clear revisions conflict even though
1195		// their sequences exceed the old accepted ones; each names the request and
