1736		}
1737		var got registerOutput
1738		if err := json.Unmarshal([]byte(out), &got); err != nil {
1739			t.Fatalf("output is not JSON: %v\n%s", err, out)
1740		}
1741		// One result per request, in input order; failed items keep their slots.
1742		if len(got.Results) != 16 {
1743			t.Fatalf("results: %+v", got.Results)
1744		}
1745		// 4-5: bind s -> a, then a plain select rotates to b; the cursor rests on b.
1746		if r := got.Results[4]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 11 {
1747			t.Fatalf("session bind: %+v", r)
1748		}
