1760		if r := got.Results[8]; !r.OK || !r.Changed || r.Revision != 2 || r.Sequence != 15 {
1761			t.Fatalf("c unhealthy: %+v", r)
1762		}
1763		// 9: a health report under the OLD revision conflicts even though its
1764		// sequence 99 exceeds anything accepted before; it names both revisions and
1765		// must not heal the new address.
1766		if r := got.Results[9]; r.OK || r.Error != "conflict" || r.Reason == "" ||
1767			r.ExpectedRevision != 1 || r.ActualRevision != 2 || r.Revision != 2 {
1768			t.Fatalf("old-revision health report: %+v", r)
