1771		// unhealthy, the session request is no_healthy: it states the reason and
1772		// the current revision and fabricates neither an instance id nor an
1773		// address. The failure must not rewrite the s -> a binding or move the
1774		// cursor off b.
1775		if r := got.Results[10]; r.OK || r.Error != "no_healthy" || r.Reason == "" ||
1776			r.Revision != 2 || r.InstanceID != "" || r.Address != "" {
