1782			t.Fatalf("fresh observation at new address: %+v", r)
1783		}
1784		// 12: the binding survived the no_healthy failure, so the session reuses a
1785		// again — with its CURRENT address and sequence, and without rotating.
1786		if r := got.Results[12]; !r.OK || r.InstanceID != "a" || r.Address != "h9:9" || r.Sequence != 1 || r.Revision != 2 {
1787			t.Fatalf("session should reuse a after its recovery: %+v", r)
