2076	// TestSelectTwoSessionKeysNoHealthyIsolation is the batch-level failure
2077	// guard. Once every instance is unhealthy, keyed and plain selections all
2078	// return no_healthy with the current revision and a reason but no fabricated
2079	// instance id, address or sequence; the failed items keep their result slots
2080	// while later valid items still apply, and the batch exits non-zero. The
2081	// failures preserve both sessions' bindings and the rotation position: an
2082	// unbound instance (c) recovers first so a surviving binding is distinguishable
2083	// from a fresh rotation, then each session's own bound instance recovers and is
2084	// reused directly with its latest sequence (a request that had lost its binding
2085	// would rotate from the parked cursor onto c instead). The plain rotation then
2086	// resumes exactly where the last real rotation stopped.
2087	func TestSelectTwoSessionKeysNoHealthyIsolation(t *testing.T) {
2088		input := `{"requests":[
2089			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"}]},
2090			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":1,"healthy":true},
2091			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":2,"healthy":true},
2092			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":3,"healthy":true},
