2200	// failingWriter fails every Write with errWriteBroken, optionally accepting the
2201	// first failAfter bytes to emulate an output destination that becomes unwritable
2202	// partway through the result document.
2203	type failingWriter struct {
2204		buf       bytes.Buffer
2205		failAfter int
2206	}
2207	
2208	var errWriteBroken = errors.New("disk on fire")
2209	
2210	func (w *failingWriter) Write(p []byte) (int, error) {
2211		if w.failAfter <= 0 {
2212			return 0, errWriteBroken
2213		}
2214		take := min(w.failAfter, len(p))
2215		n, _ := w.buf.Write(p[:take])
2216		w.failAfter -= take
2217		if take < len(p) {
2218			// A writer that accepts only part of p must return n < len(p) and the
2219			// failure without panic; json.Encoder stops at that point.
2220			return n, errWriteBroken
2221		}
2222		return n, nil
2223	}
